leviathan_prime.source:
export const envelope = [54, 46, 54];

export default function build(api) {
  const W = envelope[0];
  const H = envelope[1];
  const D = envelope[2];

  const grid = new Uint8Array(W * H * D);

  function getV(x, y, z) {
    if (x < 0 || x >= W || y < 0 || y >= H || z < 0 || z >= D) return 0;
    return grid[x + y * W + z * W * H];
  }

  function setV(x, y, z, id) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid[x + y * W + z * W * H] = id;
    }
  }

  // Palette definition
  const ID_AIR = 0;
  const ID_DARK_PRISMARINE = 1;
  const ID_PRISMARINE_BRICKS = 2;
  const ID_PRISMARINE = 3;
  const ID_SEA_LANTERN = 4;
  const ID_BONE = 5;
  const ID_CRYING_OBSIDIAN = 6;
  const ID_WARPED_WART = 7;
  const ID_DEEPSLATE_TILES = 8;
  const ID_CYAN_TERRACOTTA = 9;
  const ID_LAPIS = 10;
  const ID_SHROOMLIGHT = 11;
  const ID_POLISHED_BLACKSTONE = 12;
  const ID_OCHRE_FROGLIGHT = 13;
  const ID_SMOOTH_QUARTZ = 14;

  const PALETTE = [
    "",
    "minecraft:dark_prismarine",
    "minecraft:prismarine_bricks",
    "minecraft:prismarine",
    "minecraft:sea_lantern",
    "minecraft:bone_block",
    "minecraft:crying_obsidian",
    "minecraft:warped_wart_block",
    "minecraft:deepslate_tiles",
    "minecraft:cyan_terracotta",
    "minecraft:lapis_block",
    "minecraft:shroomlight",
    "minecraft:polished_blackstone",
    "minecraft:ochre_froglight",
    "minecraft:smooth_quartz",
  ];

  function catmullRom(p0, p1, p2, p3, t) {
    const t2 = t * t;
    const t3 = t2 * t;
    return {
      x: 0.5 * ((2 * p1.x) + (-p0.x + p2.x) * t + (2 * p0.x - 5 * p1.x + 4 * p2.x - p3.x) * t2 + (-p0.x + 3 * p1.x - 3 * p2.x + p3.x) * t3),
      y: 0.5 * ((2 * p1.y) + (-p0.y + p2.y) * t + (2 * p0.y - 5 * p1.y + 4 * p2.y - p3.y) * t2 + (-p0.y + 3 * p1.y - 3 * p2.y + p3.y) * t3),
      z: 0.5 * ((2 * p1.z) + (-p0.z + p2.z) * t + (2 * p0.z - 5 * p1.z + 4 * p2.z - p3.z) * t2 + (-p0.z + 3 * p1.z - 3 * p2.z + p3.z) * t3),
      r: 0.5 * ((2 * p1.r) + (-p0.r + p2.r) * t + (2 * p0.r - 5 * p1.r + 4 * p2.r - p3.r) * t2 + (-p0.r + 3 * p1.r - 3 * p2.r + p3.r) * t3),
    };
  }

  function fillSphere(cx, cy, cz, r, blockId, mode, ryScale = 1.0, rxScale = 1.0) {
    const minX = Math.max(0, Math.floor(cx - r * rxScale - 1));
    const maxX = Math.min(W - 1, Math.ceil(cx + r * rxScale + 1));
    const minY = Math.max(0, Math.floor(cy - r * ryScale - 1));
    const maxY = Math.min(H - 1, Math.ceil(cy + r * ryScale + 1));
    const minZ = Math.max(0, Math.floor(cz - r - 1));
    const maxZ = Math.min(D - 1, Math.ceil(cz + r + 1));

    for (let x = minX; x <= maxX; x++) {
      for (let y = minY; y <= maxY; y++) {
        for (let z = minZ; z <= maxZ; z++) {
          const dx = (x - cx) / (r * rxScale);
          const dy = (y - cy) / (r * ryScale);
          const dz = (z - cz) / r;
          const d2 = dx * dx + dy * dy + dz * dz;

          if (d2 <= 1.0) {
            let id = blockId;

            if (mode === "body") {
              if (d2 > 0.65) {
                if (dy > 0.25) {
                  id = (Math.sin(x * 1.5 + z * 1.2) > 0.25) ? ID_DEEPSLATE_TILES : ID_DARK_PRISMARINE;
                } else if (dy < -0.2) {
                  id = (Math.sin(z * 1.8) > 0.2) ? ID_CYAN_TERRACOTTA : ID_PRISMARINE_BRICKS;
                } else {
                  id = (Math.cos(x * 1.2 + y * 1.4) > 0.35) ? ID_PRISMARINE : ID_PRISMARINE_BRICKS;
                }
              } else if (d2 > 0.4) {
                id = ID_PRISMARINE;
              } else {
                id = ID_WARPED_WART;
              }
            } else if (mode === "tentacle") {
              if (d2 > 0.6) {
                id = ID_DARK_PRISMARINE;
              } else if (d2 > 0.3) {
                id = ID_PRISMARINE_BRICKS;
              } else {
                id = ID_PRISMARINE;
              }
            } else if (mode === "horn") {
              if (d2 > 0.5) {
                id = ID_DEEPSLATE_TILES;
              } else {
                id = ID_POLISHED_BLACKSTONE;
              }
            }

            setV(x, y, z, id);
          }
        }
      }
    }
  }

  function drawSpline(pts, blockId, mode, ryScale = 1.0, rxScale = 1.0) {
    if (pts.length < 2) return;
    const cp = [pts[0], ...pts, pts[pts.length - 1]];

    for (let seg = 0; seg < cp.length - 3; seg++) {
      const p0 = cp[seg];
      const p1 = cp[seg + 1];
      const p2 = cp[seg + 2];
      const p3 = cp[seg + 3];

      const dist = Math.hypot(p2.x - p1.x, p2.y - p1.y, p2.z - p1.z);
      const steps = Math.max(8, Math.ceil(dist * 3.5));

      for (let s = 0; s <= steps; s++) {
        const t = s / steps;
        const pt = catmullRom(p0, p1, p2, p3, t);
        fillSphere(pt.x, pt.y, pt.z, Math.max(0.6, pt.r), blockId, mode, ryScale, rxScale);
      }
    }
  }

  // 1. Water surge whirlpool base & ocean crests
  const surgeCenterX = 27;
  const surgeCenterZ = 33;

  for (let x = 6; x <= 48; x++) {
    for (let z = 12; z <= 52; z++) {
      const dx = x - surgeCenterX;
      const dz = z - surgeCenterZ;
      const dist = Math.hypot(dx, dz);

      if (dist <= 21) {
        const wave = Math.sin(dist * 0.45 - Math.atan2(dz, dx) * 3) * 1.2;
        const hMax = Math.max(1, Math.round(5.5 * Math.cos((dist / 21) * (Math.PI / 2)) + wave));

        for (let y = 0; y <= hMax; y++) {
          let id = ID_DARK_PRISMARINE;
          if (y === hMax) {
            id = (dist > 13 && (x + z) % 3 === 0) ? ID_SEA_LANTERN : (y >= 4 ? ID_PRISMARINE : ID_PRISMARINE_BRICKS);
          } else if (y >= hMax - 1) {
            id = ID_PRISMARINE;
          } else {
            id = (dist < 10) ? ID_LAPIS : ID_DARK_PRISMARINE;
          }
          setV(x, y, z, id);
        }

        const groundH = api.heightAt(x, z);
        if (groundH > 0) {
          for (let y = 0; y <= groundH; y++) {
            setV(x, y, z, ID_DARK_PRISMARINE);
          }
        }
      }
    }
  }

  // Vertical water splash spouts
  const splashSpouts = [
    { x: 14, z: 26, h: 9, r: 1.8 },
    { x: 40, z: 26, h: 9, r: 1.8 },
    { x: 12, z: 40, h: 8, r: 1.6 },
    { x: 42, z: 40, h: 8, r: 1.6 },
    { x: 27, z: 50, h: 10, r: 2.0 },
    { x: 19, z: 18, h: 8, r: 1.5 },
    { x: 35, z: 18, h: 8, r: 1.5 },
  ];

  for (const sp of splashSpouts) {
    for (let y = 2; y <= sp.h; y++) {
      const r = sp.r * (1.0 - (y / (sp.h + 2)));
      fillSphere(sp.x, y, sp.z, Math.max(0.8, r), (y >= sp.h - 1) ? ID_SEA_LANTERN : ID_PRISMARINE, "water");
    }
  }

  // 2. Serpentine Torso & Neck
  const torsoPts = [
    { x: 27, y: 1, z: 38, r: 7.8 },
    { x: 27, y: 7, z: 34, r: 7.4 },
    { x: 27, y: 14, z: 28, r: 6.8 },
    { x: 27, y: 21, z: 20, r: 6.2 },
    { x: 27, y: 27, z: 13, r: 5.4 },
    { x: 27, y: 30, z: 8, r: 4.8 },
  ];
  drawSpline(torsoPts, ID_DARK_PRISMARINE, "body", 1.15, 1.0);

  // 3. Upper Jaw (Snout lunging North)
  const upperJawPts = [
    { x: 27, y: 30, z: 8, r: 4.8 },
    { x: 27, y: 32, z: 5, r: 3.8 },
    { x: 27, y: 31, z: 2, r: 2.4 },
  ];
  drawSpline(upperJawPts, ID_DARK_PRISMARINE, "body", 0.9, 1.0);

  // 4. Lower Jaw (Dropped wide open)
  const lowerJawPts = [
    { x: 27, y: 25, z: 10, r: 4.2 },
    { x: 27, y: 21, z: 6, r: 3.6 },
    { x: 27, y: 19, z: 2, r: 2.2 },
  ];
  drawSpline(lowerJawPts, ID_DARK_PRISMARINE, "body", 0.85, 0.95);

  // 5. Cavernous Gaping Maw & Glowing Gullet
  for (let x = 23; x <= 31; x++) {
    for (let y = 22; y <= 29; y++) {
      for (let z = 2; z <= 9; z++) {
        const dx = (x - 27) / 4.0;
        const dy = (y - 25.5) / 3.5;
        const dz = (z - 5.5) / 4.0;
        if (dx * dx + dy * dy + dz * dz < 0.85) {
          if (z >= 7) {
            setV(x, y, z, (z === 8 && y === 25 && x === 27) ? ID_SHROOMLIGHT : ID_SEA_LANTERN);
          } else {
            setV(x, y, z, ID_AIR);
          }
        }
      }
    }
  }

  for (let x = 24; x <= 30; x++) {
    for (let y = 23; y <= 28; y++) {
      if (getV(x, y, 9) === ID_AIR || getV(x, y, 9) === ID_WARPED_WART) {
        setV(x, y, 9, ID_CRYING_OBSIDIAN);
      }
      if (getV(x, y, 10) === ID_AIR || getV(x, y, 10) === ID_WARPED_WART) {
        setV(x, y, 10, ID_SEA_LANTERN);
      }
    }
  }

  // 6. Colossal Bone Fangs
  const upperFangs = [
    { x: 25, yTop: 30, yBot: 27, z: 2 },
    { x: 29, yTop: 30, yBot: 27, z: 2 },
    { x: 23, yTop: 30, yBot: 26, z: 4 },
    { x: 31, yTop: 30, yBot: 26, z: 4 },
    { x: 22, yTop: 29, yBot: 25, z: 6 },
    { x: 32, yTop: 29, yBot: 25, z: 6 },
    { x: 23, yTop: 28, yBot: 25, z: 8 },
    { x: 31, yTop: 28, yBot: 25, z: 8 },
  ];
  for (const fang of upperFangs) {
    for (let y = fang.yBot; y <= fang.yTop; y++) {
      setV(fang.x, y, fang.z, (y === fang.yBot) ? ID_SMOOTH_QUARTZ : ID_BONE);
    }
  }

  const lowerFangs = [
    { x: 25, yBot: 20, yTop: 23, z: 2 },
    { x: 29, yBot: 20, yTop: 23, z: 2 },
    { x: 23, yBot: 21, yTop: 25, z: 4 },
    { x: 31, yBot: 21, yTop: 25, z: 4 },
    { x: 22, yBot: 21, yTop: 26, z: 6 },
    { x: 32, yBot: 21, yTop: 26, z: 6 },
    { x: 23, yBot: 22, yTop: 26, z: 8 },
    { x: 31, yBot: 22, yTop: 26, z: 8 },
  ];
  for (const fang of lowerFangs) {
    for (let y = fang.yBot; y <= fang.yTop; y++) {
      setV(fang.x, y, fang.z, (y === fang.yTop) ? ID_SMOOTH_QUARTZ : ID_BONE);
    }
  }

  // 7. Glowing Eyes & Facial Sensory Nodes
  setV(21, 32, 6, ID_OCHRE_FROGLIGHT);
  setV(22, 32, 6, ID_SEA_LANTERN);
  setV(21, 31, 6, ID_POLISHED_BLACKSTONE);
  setV(21, 33, 6, ID_DARK_PRISMARINE);
  setV(20, 32, 6, ID_DEEPSLATE_TILES);
  setV(21, 30, 6, ID_CRYING_OBSIDIAN);
  setV(21, 29, 7, ID_CRYING_OBSIDIAN);

  setV(33, 32, 6, ID_OCHRE_FROGLIGHT);
  setV(32, 32, 6, ID_SEA_LANTERN);
  setV(33, 31, 6, ID_POLISHED_BLACKSTONE);
  setV(33, 33, 6, ID_DARK_PRISMARINE);
  setV(34, 32, 6, ID_DEEPSLATE_TILES);
  setV(33, 30, 6, ID_CRYING_OBSIDIAN);
  setV(33, 29, 7, ID_CRYING_OBSIDIAN);

  setV(24, 33, 3, ID_SEA_LANTERN);
  setV(30, 33, 3, ID_SEA_LANTERN);
  setV(23, 31, 4, ID_OCHRE_FROGLIGHT);
  setV(31, 31, 4, ID_OCHRE_FROGLIGHT);

  // 8. Horns, Crests & Barbels
  const centralCrest = [
    { x: 27, y: 34, z: 9, r: 2.2 },
    { x: 27, y: 39, z: 13, r: 1.8 },
    { x: 27, y: 43, z: 18, r: 1.2 },
    { x: 27, y: 45, z: 23, r: 0.6 },
  ];
  drawSpline(centralCrest, ID_DEEPSLATE_TILES, "horn");

  const leftHorn = [
    { x: 23, y: 33, z: 9, r: 1.8 },
    { x: 18, y: 37, z: 13, r: 1.5 },
    { x: 14, y: 41, z: 18, r: 1.0 },
    { x: 12, y: 44, z: 23, r: 0.6 },
  ];
  drawSpline(leftHorn, ID_DEEPSLATE_TILES, "horn");

  const rightHorn = [
    { x: 31, y: 33, z: 9, r: 1.8 },
    { x: 36, y: 37, z: 13, r: 1.5 },
    { x: 40, y: 41, z: 18, r: 1.0 },
    { x: 42, y: 44, z: 23, r: 0.6 },
  ];
  drawSpline(rightHorn, ID_DEEPSLATE_TILES, "horn");

  const leftMandible = [
    { x: 21, y: 24, z: 9, r: 1.6 },
    { x: 16, y: 22, z: 6, r: 1.2 },
    { x: 14, y: 18, z: 3, r: 0.7 },
  ];
  drawSpline(leftMandible, ID_DARK_PRISMARINE, "tentacle");

  const rightMandible = [
    { x: 33, y: 24, z: 9, r: 1.6 },
    { x: 38, y: 22, z: 6, r: 1.2 },
    { x: 40, y: 18, z: 3, r: 0.7 },
  ];
  drawSpline(rightMandible, ID_DARK_PRISMARINE, "tentacle");

  // 9. Armored Dorsal Fin Crests
  const dorsalFins = [
    { zCenter: 35, yBase: 9, height: 5, len: 3 },
    { zCenter: 29, yBase: 16, height: 6, len: 3 },
    { zCenter: 23, yBase: 23, height: 7, len: 4 },
    { zCenter: 17, yBase: 28, height: 6, len: 3 },
    { zCenter: 12, yBase: 31, height: 4, len: 2 },
  ];

  for (const fin of dorsalFins) {
    for (let dz = -Math.floor(fin.len / 2); dz <= Math.floor(fin.len / 2); dz++) {
      const z = fin.zCenter + dz;
      const h = fin.height - Math.abs(dz);
      for (let y = fin.yBase; y <= fin.yBase + h; y++) {
        if (y === fin.yBase + h) {
          setV(27, y, z, ID_SMOOTH_QUARTZ);
        } else if (y >= fin.yBase + h - 2) {
          setV(27, y, z, ID_DEEPSLATE_TILES);
        } else {
          setV(27, y, z, (dz === 0) ? ID_SEA_LANTERN : ID_DARK_PRISMARINE);
        }
        if (Math.abs(dz) === 0 && y <= fin.yBase + h - 2) {
          setV(26, y, z, ID_DARK_PRISMARINE);
          setV(28, y, z, ID_DARK_PRISMARINE);
        }
      }
    }
  }

  // 10. Six Grand Tentacles with Bioluminescent Suckers
  const tentacles = [
    // Front-Left
    {
      pts: [
        { x: 21, y: 12, z: 23, r: 3.8 },
        { x: 15, y: 15, z: 16, r: 3.2 },
        { x: 9, y: 20, z: 10, r: 2.6 },
        { x: 5, y: 27, z: 6, r: 2.1 },
        { x: 6, y: 35, z: 5, r: 1.6 },
        { x: 10, y: 41, z: 7, r: 1.2 },
        { x: 15, y: 43, z: 11, r: 0.7 },
      ],
      suckerOffset: { dx: 1, dy: -1, dz: 1 },
    },
    // Front-Right
    {
      pts: [
        { x: 33, y: 12, z: 23, r: 3.8 },
        { x: 39, y: 16, z: 16, r: 3.2 },
        { x: 45, y: 19, z: 10, r: 2.6 },
        { x: 47, y: 18, z: 4, r: 2.1 },
        { x: 45, y: 12, z: 2, r: 1.6 },
        { x: 39, y: 6, z: 2, r: 1.2 },
        { x: 33, y: 2, z: 3, r: 0.7 },
      ],
      suckerOffset: { dx: -1, dy: 1, dz: 1 },
    },
    // Mid-Left
    {
      pts: [
        { x: 20, y: 15, z: 28, r: 3.5 },
        { x: 12, y: 21, z: 27, r: 3.0 },
        { x: 5, y: 28, z: 24, r: 2.4 },
        { x: 3, y: 35, z: 19, r: 1.8 },
        { x: 5, y: 41, z: 14, r: 1.3 },
        { x: 9, y: 43, z: 11, r: 0.7 },
      ],
      suckerOffset: { dx: 1, dy: -1, dz: 0 },
    },
    // Mid-Right
    {
      pts: [
        { x: 34, y: 15, z: 28, r: 3.5 },
        { x: 42, y: 21, z: 27, r: 3.0 },
        { x: 49, y: 28, z: 24, r: 2.4 },
        { x: 51, y: 35, z: 19, r: 1.8 },
        { x: 49, y: 41, z: 14, r: 1.3 },
        { x: 45, y: 43, z: 11, r: 0.7 },
      ],
      suckerOffset: { dx: -1, dy: -1, dz: 0 },
    },
    // Rear-Left
    {
      pts: [
        { x: 20, y: 6, z: 37, r: 3.8 },
        { x: 13, y: 10, z: 42, r: 3.1 },
        { x: 6, y: 16, z: 46, r: 2.4 },
        { x: 4, y: 24, z: 45, r: 1.8 },
        { x: 8, y: 30, z: 41, r: 1.3 },
        { x: 14, y: 33, z: 37, r: 0.7 },
      ],
      suckerOffset: { dx: 1, dy: -1, dz: -1 },
    },
    // Rear-Right
    {
      pts: [
        { x: 34, y: 6, z: 37, r: 3.8 },
        { x: 41, y: 10, z: 42, r: 3.1 },
        { x: 48, y: 16, z: 46, r: 2.4 },
        { x: 50, y: 24, z: 45, r: 1.8 },
        { x: 46, y: 30, z: 41, r: 1.3 },
        { x: 40, y: 33, z: 37, r: 0.7 },
      ],
      suckerOffset: { dx: -1, dy: -1, dz: -1 },
    },
  ];

  for (const tentacle of tentacles) {
    drawSpline(tentacle.pts, ID_DARK_PRISMARINE, "tentacle");

    const cp = [tentacle.pts[0], ...tentacle.pts, tentacle.pts[tentacle.pts.length - 1]];
    for (let seg = 0; seg < cp.length - 3; seg++) {
      for (let step = 1; step <= 4; step++) {
        const t = step / 4.5;
        const pt = catmullRom(cp[seg], cp[seg + 1], cp[seg + 2], cp[seg + 3], t);
        if (pt.r > 1.2) {
          const sx = Math.round(pt.x + (tentacle.suckerOffset.dx * pt.r * 0.75));
          const sy = Math.round(pt.y + (tentacle.suckerOffset.dy * pt.r * 0.75));
          const sz = Math.round(pt.z + (tentacle.suckerOffset.dz * pt.r * 0.75));

          if (sx >= 0 && sx < W && sy >= 0 && sy < H && sz >= 0 && sz < D) {
            setV(sx, sy, sz, ID_SEA_LANTERN);
            for (let ox = -1; ox <= 1; ox++) {
              for (let oy = -1; oy <= 1; oy++) {
                if (Math.abs(ox) + Math.abs(oy) === 1) {
                  const rx = sx + ox;
                  const ry = sy + oy;
                  if (getV(rx, ry, sz) === ID_DARK_PRISMARINE || getV(rx, ry, sz) === ID_PRISMARINE) {
                    setV(rx, ry, sz, ID_OCHRE_FROGLIGHT);
                  }
                }
              }
            }
          }
        }
      }
    }
  }

  // 11. Lateral Bioluminescent Lines along Torso
  for (let s = 0; s <= 24; s++) {
    const t = s / 24;
    const cp = [torsoPts[0], ...torsoPts, torsoPts[torsoPts.length - 1]];
    const seg = Math.min(cp.length - 4, Math.floor(t * (cp.length - 3)));
    const localT = (t * (cp.length - 3)) - seg;
    const pt = catmullRom(cp[seg], cp[seg + 1], cp[seg + 2], cp[seg + 3], localT);

    const leftX = Math.round(pt.x - pt.r - 0.2);
    const rightX = Math.round(pt.x + pt.r + 0.2);
    const midY = Math.round(pt.y);
    const midZ = Math.round(pt.z);

    if (s % 2 === 0) {
      setV(leftX, midY, midZ, ID_SEA_LANTERN);
      setV(rightX, midY, midZ, ID_SEA_LANTERN);
    } else {
      setV(leftX, midY, midZ, ID_CRYING_OBSIDIAN);
      setV(rightX, midY, midZ, ID_CRYING_OBSIDIAN);
    }
  }

  // 12. Direct block emission to world
  for (let z = 0; z < D; z++) {
    for (let y = 0; y < H; y++) {
      for (let x = 0; x < W; x++) {
        const id = getV(x, y, z);
        if (id > 0) {
          api.set(x, y, z, PALETTE[id]);
        }
      }
    }
  }

  return {
    name: "Leviathan Prime",
    seatY: 0,
    anchors: {
      front: [27, 26, 0],
      maw: [27, 26, 2],
      eye_left: [21, 32, 6],
      eye_right: [33, 32, 6],
    },
  };
}

colossus_defense_turret.source:
export const envelope = [19, 36, 19];

export default function build(api) {
  const [W, H, D] = api.size;
  const grid = new Map();

  function set(x, y, z, block) {
    if (x < 0 || x >= W || y < 0 || y >= H || z < 0 || z >= D) return;
    grid.set(`${x},${y},${z}`, block);
  }

  function get(x, y, z) {
    return grid.get(`${x},${y},${z}`);
  }

  const theme = api.theme || {};
  const stone = theme.stone || {};

  // Neoclassical quartz / marble family
  const quartz = stone.primary || "minecraft:smooth_quartz";
  const quartzBricks = stone.accent || "minecraft:quartz_bricks";
  const quartzStairs = stone.stairs || "minecraft:quartz_stairs";
  const quartzSlab = stone.slab || "minecraft:quartz_slab";
  const quartzPillarY = "minecraft:quartz_pillar[axis=y]";
  const quartzPillarZ = "minecraft:quartz_pillar[axis=z]";
  const chiseledQuartz = "minecraft:chiseled_quartz_block";

  // Bronze colossus sculpture family
  const copper = "minecraft:cut_copper";
  const exposedCopper = "minecraft:exposed_cut_copper";
  const copperBlock = "minecraft:copper_block";
  const copperStairs = "minecraft:cut_copper_stairs";
  const copperSlab = "minecraft:cut_copper_slab[type=bottom]";

  // Retrofitted coastal defense artillery / military armor family
  const deepslate = "minecraft:polished_deepslate";
  const deepslateTiles = "minecraft:deepslate_tiles";
  const deepslateStairs = "minecraft:polished_deepslate_stairs";
  const deepslateWall = "minecraft:polished_deepslate_wall";
  const ironBlock = "minecraft:iron_block";
  const ironBars = "minecraft:iron_bars";
  const seaLantern = "minecraft:sea_lantern";
  const darkPrismarine = "minecraft:dark_prismarine";
  const cryingObsidian = "minecraft:crying_obsidian";

  // ==========================================
  // 1. SUBSTRUCTURE, FOUNDATION & PLINTH (y=0..8)
  // ==========================================
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const dx = Math.abs(x - 9);
      const dz = Math.abs(z - 9);
      const inPlinth = dx <= 8 && dz <= 8 && (dx + dz <= 12);

      if (inPlinth) {
        const gh = Math.min(0, Math.floor(api.heightAt(x, z)));
        for (let y = gh; y <= 0; y++) {
          set(x, y, z, (dx >= 7 || dz >= 7) ? deepslateTiles : quartzBricks);
        }
      }
    }
  }

  // Tier 1 Base Course (y = 0..1)
  for (let x = 1; x <= 17; x++) {
    for (let z = 1; z <= 17; z++) {
      const dx = Math.abs(x - 9);
      const dz = Math.abs(z - 9);

      if (dx <= 8 && dz <= 8 && (dx + dz <= 12)) {
        set(x, 0, z, (dx >= 7 || dz >= 7 || dx + dz === 12) ? deepslateTiles : quartzBricks);

        if (dx === 8 || dz === 8 || dx + dz === 12) {
          if (dz === 8 && z === 1) set(x, 1, z, `${deepslateStairs}[facing=north,half=bottom]`);
          else if (dz === 8 && z === 17) set(x, 1, z, `${deepslateStairs}[facing=south,half=bottom]`);
          else if (dx === 8 && x === 1) set(x, 1, z, `${deepslateStairs}[facing=west,half=bottom]`);
          else if (dx === 8 && x === 17) set(x, 1, z, `${deepslateStairs}[facing=east,half=bottom]`);
          else set(x, 1, z, deepslateTiles);
        } else {
          set(x, 1, z, quartzBricks);
        }
      }
    }
  }

  // Plinth Walls & Corner Pilasters (y = 1..6)
  for (let y = 1; y <= 6; y++) {
    for (let x = 2; x <= 16; x++) {
      for (let z = 2; z <= 16; z++) {
        const dx = Math.abs(x - 9);
        const dz = Math.abs(z - 9);
        const onWallRing = dx <= 7 && dz <= 7 && (dx + dz <= 11) && (dx >= 4 || dz >= 4);

        if (onWallRing) {
          // Corner pilasters
          const isPilaster = (dx === 6 && dz === 6) || (dx === 7 && dz <= 2) || (dz === 7 && dx <= 2);
          if (isPilaster) {
            set(x, y, z, (y === 1 || y === 6) ? chiseledQuartz : quartzPillarY);
          } else {
            // Retrofitted defense panels with observation / conduit slits
            if (y === 3 && (dx === 7 || dz === 7)) {
              set(x, y, z, seaLantern);
            } else if (y === 2 || y === 4) {
              set(x, y, z, deepslateTiles);
            } else {
              set(x, y, z, quartzBricks);
            }
          }
        }
      }
    }
  }

  // Plinth Ceiling / Interior Floor Setup (y = 0..6)
  for (let x = 5; x <= 13; x++) {
    for (let z = 5; z <= 13; z++) {
      set(x, 0, z, ((x + z) % 2 === 0) ? deepslateTiles : quartzBricks);
      set(x, 6, z, quartz);
      // Ensure interior is clear for compiler fit-out
      for (let y = 1; y <= 5; y++) {
        grid.delete(`${x},${y},${z}`);
      }
    }
  }

  // South Entrance Corridor (Metropolis approach, z=14..17, x=8..10, y=1..3)
  for (let z = 14; z <= 17; z++) {
    for (let x = 8; x <= 10; x++) {
      for (let y = 1; y <= 3; y++) {
        grid.delete(`${x},${y},${z}`);
      }
      set(x, 0, z, deepslateTiles);
    }
  }
  // Doorway arch & flanking columns
  set(7, 1, 16, chiseledQuartz);
  set(7, 2, 16, quartzPillarY);
  set(7, 3, 16, quartzPillarY);
  set(11, 1, 16, chiseledQuartz);
  set(11, 2, 16, quartzPillarY);
  set(11, 3, 16, quartzPillarY);
  set(8, 4, 16, `${deepslateStairs}[facing=east,half=top]`);
  set(9, 4, 16, deepslateTiles);
  set(10, 4, 16, `${deepslateStairs}[facing=west,half=top]`);

  // Plinth Cornice & Turret Observation Deck (y = 7..8)
  for (let x = 1; x <= 17; x++) {
    for (let z = 1; z <= 17; z++) {
      const dx = Math.abs(x - 9);
      const dz = Math.abs(z - 9);

      if (dx <= 8 && dz <= 8 && (dx + dz <= 12)) {
        // Cornice corbeling at y=7
        if (dx === 8 || dz === 8 || dx + dz === 12) {
          if (z === 1) set(x, 7, z, `${quartzStairs}[facing=north,half=top]`);
          else if (z === 17) set(x, 7, z, `${quartzStairs}[facing=south,half=top]`);
          else if (x === 1) set(x, 7, z, `${quartzStairs}[facing=west,half=top]`);
          else if (x === 17) set(x, 7, z, `${quartzStairs}[facing=east,half=top]`);
          else set(x, 7, z, quartz);
        } else {
          set(x, 7, z, quartz);
        }

        // Deck Walkway & Parapet at y=8
        if (dx <= 7 && dz <= 7 && (dx + dz <= 11)) {
          const onEdge = dx === 7 || dz === 7 || dx + dz === 11;
          if (onEdge) {
            set(x, 8, z, deepslateWall);
          } else {
            set(x, 8, z, (dx * dx + dz * dz <= 25) ? deepslateTiles : quartzBricks);
          }
        }
      }
    }
  }

  // Perimeter Searchlights on Plinth Corners (y=8..9)
  const spotCorners = [[3, 3, "north"], [15, 3, "north"], [3, 15, "south"], [15, 15, "south"]];
  for (const [cx, cz, face] of spotCorners) {
    set(cx, 8, cz, ironBlock);
    set(cx, 9, cz, seaLantern);
    set(cx, 10, cz, `${deepslateStairs}[facing=${face},half=top]`);
  }

  // ==========================================
  // 2. TURRET TRAVERSE RING & PEDESTAL (y=9..11)
  // ==========================================
  for (let x = 4; x <= 14; x++) {
    for (let z = 4; z <= 14; z++) {
      const distSq = (x - 9) * (x - 9) + (z - 9) * (z - 9);
      if (distSq <= 26) {
        set(x, 9, z, (distSq >= 18) ? copper : deepslateTiles);
      }
      if (distSq <= 20) {
        set(x, 10, z, (distSq >= 13) ? ironBlock : deepslate);
      }
      if (distSq <= 16) {
        set(x, 11, z, (distSq >= 9) ? quartz : copperBlock);
      }
    }
  }

  // Hydraulic Traverse Stabilizers
  set(4, 9, 9, deepslate);
  set(4, 10, 9, ironBlock);
  set(14, 9, 9, deepslate);
  set(14, 10, 9, ironBlock);
  set(9, 9, 4, deepslate);
  set(9, 10, 4, ironBlock);
  set(9, 9, 14, deepslate);
  set(9, 10, 14, ironBlock);

  // ==========================================
  // 3. THE COLOSSUS LOWER BODY (y=11..19)
  // ==========================================
  // Left Leg & Sabaton (West side, braced forward toward North)
  // Foot (y=11..12)
  for (let x = 5; x <= 7; x++) {
    for (let z = 7; z <= 10; z++) {
      set(x, 11, z, copper);
      set(x, 12, z, (z === 7) ? `${copperStairs}[facing=north,half=bottom]` : copper);
    }
  }
  // Greave / Shin (y=13..15)
  for (let y = 13; y <= 15; y++) {
    for (let x = 5; x <= 7; x++) {
      for (let z = 8; z <= 10; z++) {
        set(x, y, z, (z === 8) ? exposedCopper : copper);
      }
    }
    set(6, y, 11, deepslateWall); // Hydraulic leg actuator
  }
  // Knee (y=16)
  for (let x = 5; x <= 7; x++) {
    for (let z = 8; z <= 10; z++) {
      set(x, 16, z, copper);
    }
  }
  set(6, 16, 7, chiseledQuartz); // Classical knee boss

  // Thigh (y=17..18)
  for (let y = 17; y <= 18; y++) {
    for (let x = 5; x <= 7; x++) {
      for (let z = 8; z <= 10; z++) {
        set(x, y, z, copper);
      }
    }
  }

  // Right Leg & Sabaton (East side)
  // Foot (y=11..12)
  for (let x = 11; x <= 13; x++) {
    for (let z = 8; z <= 11; z++) {
      set(x, 11, z, copper);
      set(x, 12, z, (z === 8) ? `${copperStairs}[facing=north,half=bottom]` : copper);
    }
  }
  // Greave / Shin (y=13..15)
  for (let y = 13; y <= 15; y++) {
    for (let x = 11; x <= 13; x++) {
      for (let z = 9; z <= 11; z++) {
        set(x, y, z, (z === 9) ? exposedCopper : copper);
      }
    }
    set(12, y, 12, deepslateWall);
  }
  // Knee (y=16)
  for (let x = 11; x <= 13; x++) {
    for (let z = 8; z <= 10; z++) {
      set(x, 16, z, copper);
    }
  }
  set(12, 16, 7, chiseledQuartz);

  // Thigh (y=17..18)
  for (let y = 17; y <= 18; y++) {
    for (let x = 11; x <= 13; x++) {
      for (let z = 8; z <= 10; z++) {
        set(x, y, z, copper);
      }
    }
  }

  // Armored Pelvis & Pteruges (Hellenic War Skirt) (y=18..20)
  for (let y = 19; y <= 20; y++) {
    for (let x = 6; x <= 12; x++) {
      for (let z = 7; z <= 11; z++) {
        set(x, y, z, copperBlock);
      }
    }
  }
  // Front Hanging Pteruges (y=18..19, z=7)
  for (let x = 6; x <= 12; x++) {
    set(x, 18, 7, (x % 2 === 0) ? `${quartzSlab}[type=bottom]` : copperSlab);
    set(x, 19, 7, (x % 2 === 0) ? quartz : exposedCopper);
  }
  // Belt with central power capacitor (y=20)
  for (let x = 6; x <= 12; x++) {
    set(x, 20, 7, chiseledQuartz);
    set(x, 20, 11, deepslateTiles);
  }
  set(9, 20, 6, seaLantern); // Belt power core

  // ==========================================
  // 4. BRONZE CUIRASS & REAR SUPER-REACTOR (y=21..26)
  // ==========================================
  for (let y = 21; y <= 26; y++) {
    for (let x = 6; x <= 12; x++) {
      for (let z = 8; z <= 11; z++) {
        set(x, y, z, copper);
      }
    }
  }

  // Muscled Anatomical Front Cuirass (z=7, y=21..26)
  for (let y = 21; y <= 24; y++) {
    set(7, y, 7, exposedCopper);
    set(8, y, 7, copper);
    set(9, y, 7, darkPrismarine); // Central energy spine
    set(10, y, 7, copper);
    set(11, y, 7, exposedCopper);
  }
  // Pectoral Plates (y=25..26, z=7)
  set(7, 25, 7, `${copperStairs}[facing=north,half=bottom]`);
  set(8, 25, 7, `${copperStairs}[facing=north,half=bottom]`);
  set(10, 25, 7, `${copperStairs}[facing=north,half=bottom]`);
  set(11, 25, 7, `${copperStairs}[facing=north,half=bottom]`);
  set(7, 26, 7, quartz);
  set(8, 26, 7, quartz);
  set(9, 26, 7, seaLantern);
  set(10, 26, 7, quartz);
  set(11, 26, 7, quartz);

  // Retrofitted Spine Super-Reactor & Heat Sinks (z=11..13, y=21..26)
  for (let y = 21; y <= 25; y++) {
    for (let x = 7; x <= 11; x++) {
      set(x, y, 12, deepslateTiles);
    }
    // Heat radiator cooling fins
    set(7, y, 13, ironBars);
    set(8, y, 13, deepslateWall);
    set(10, y, 13, deepslateWall);
    set(11, y, 13, ironBars);
  }
  // Glowing Reactor Exhaust Ports
  set(9, 23, 12, cryingObsidian);
  set(9, 24, 12, seaLantern);
  set(9, 25, 12, cryingObsidian);

  // Armored Feed Cables arching over shoulders
  for (let z = 8; z <= 12; z++) {
    set(6, 26, z, darkPrismarine);
    set(12, 26, z, darkPrismarine);
  }

  // ==========================================
  // 5. RETROFITTED HEAVY COASTAL RAILGUN (y=21..28)
  // ==========================================
  // Pauldrons (Shoulder Armor)
  for (let x = 4; x <= 6; x++) {
    for (let z = 7; z <= 10; z++) {
      set(x, 25, z, quartz);
      set(x, 26, z, chiseledQuartz);
    }
  }
  for (let x = 12; x <= 14; x++) {
    for (let z = 7; z <= 10; z++) {
      set(x, 25, z, quartz);
      set(x, 26, z, chiseledQuartz);
    }
  }

  // Colossus Arms Bracing the Artillery System
  // Left arm (West) holding ammo-flux housing
  set(5, 24, 6, copper);
  set(5, 23, 6, copper);
  set(5, 23, 5, ironBlock);
  set(5, 22, 5, deepslate);

  // Right arm (East) holding firing carriage
  set(13, 24, 6, copper);
  set(13, 23, 6, copper);
  set(13, 23, 5, ironBlock);
  set(13, 22, 5, deepslate);

  // Heavy Breech Assembly (x: 6..12, y: 22..25, z: 5..7)
  for (let y = 22; y <= 25; y++) {
    for (let x = 6; x <= 12; x++) {
      for (let z = 5; z <= 7; z++) {
        set(x, y, z, deepslateTiles);
      }
    }
  }

  // Twin Heavy Railgun Barrels (Aimed North toward Z=0 / Sea Monsters)
  // Left Barrel Axis: X=7, Y=23..24
  // Right Barrel Axis: X=11, Y=23..24
  const barrelXs = [7, 11];

  for (const bx of barrelXs) {
    for (let z = 1; z <= 6; z++) {
      // Lower barrel channel
      set(bx, 22, z, deepslate);
      set(bx - 1, 23, z, deepslateTiles);
      set(bx + 1, 23, z, deepslateTiles);
      set(bx, 23, z, seaLantern); // Linear accelerator magnetic coil core

      // Upper barrel channel
      set(bx - 1, 24, z, deepslateTiles);
      set(bx + 1, 24, z, deepslateTiles);
      set(bx, 24, z, ironBlock);
      set(bx, 25, z, darkPrismarine);
    }

    // Muzzle Brakes at z = 1..2
    set(bx - 1, 23, 1, `${deepslateStairs}[facing=south,half=bottom]`);
    set(bx + 1, 23, 1, `${deepslateStairs}[facing=south,half=bottom]`);
    set(bx - 1, 24, 1, `${deepslateStairs}[facing=south,half=top]`);
    set(bx + 1, 24, 1, `${deepslateStairs}[facing=south,half=top]`);

    // High-energy Discharge Prongs pointing North
    set(bx, 23, 0, "minecraft:lightning_rod[facing=north]");
    set(bx, 24, 0, "minecraft:lightning_rod[facing=north]");
  }

  // Central Sensor & Targeting Matrix Pod (x=9, y=22..24, z=3..5)
  for (let z = 3; z <= 5; z++) {
    set(9, 22, z, ironBlock);
    set(9, 23, z, darkPrismarine);
    set(9, 24, z, chiseledQuartz);
  }
  // Optical Rangefinder Lens pointing North
  set(9, 23, 2, seaLantern);
  set(9, 24, 2, "minecraft:lightning_rod[facing=north]");

  // ==========================================
  // 6. COLOSSUS HEAD, HELMET & CREST (y=26..35)
  // ==========================================
  // Neck & Gorget (y=26..27, x: 8..10, z: 8..9)
  for (let x = 8; x <= 10; x++) {
    for (let z = 8; z <= 9; z++) {
      set(x, 27, z, copper);
    }
  }

  // Heroic Facial Structure & Cybernetic Visor (y=28..30, z=7)
  // Jaw & Chin (y=28)
  set(8, 28, 7, copper);
  set(9, 28, 7, `${copperStairs}[facing=north,half=bottom]`);
  set(10, 28, 7, copper);

  // Mid Face (y=29)
  set(8, 29, 7, exposedCopper);
  set(9, 29, 7, `${copperStairs}[facing=north,half=top]`); // Chiseled Hellenic nose
  set(10, 29, 7, copper);

  // Eyes & Brow (y=30)
  set(8, 30, 7, seaLantern); // Retrofitted targeting monocular optic
  set(9, 30, 7, copper);
  set(10, 30, 7, exposedCopper);

  // Head Core & Helmet Cheekguards (y=28..30, x: 7..11, z: 8..10)
  for (let y = 28; y <= 30; y++) {
    for (let x = 7; x <= 11; x++) {
      for (let z = 8; z <= 10; z++) {
        set(x, y, z, copperBlock);
      }
    }
    // Cheekguards
    set(7, y, 7, `${copperStairs}[facing=east,half=bottom]`);
    set(11, y, 7, `${copperStairs}[facing=west,half=bottom]`);
  }

  // Corinthian Helmet Dome & Golden Laurel Brow (y=31..32)
  for (let x = 7; x <= 11; x++) {
    for (let z = 7; z <= 10; z++) {
      set(x, 31, z, copperBlock);
      if (x >= 8 && x <= 10 && z >= 8 && z <= 9) {
        set(x, 32, z, copperBlock);
      }
    }
    set(x, 31, 7, chiseledQuartz); // Laurel brow band
  }

  // High Transverse Spartan / Hellenic Crest (y=32..35)
  // Crest Riser (y=32)
  for (let z = 6; z <= 11; z++) {
    set(9, 32, z, quartz);
  }
  // Sweeping Plume (y=33..34)
  set(9, 33, 6, `${quartzStairs}[facing=north,half=bottom]`);
  for (let z = 7; z <= 10; z++) {
    set(9, 33, z, quartz);
    set(8, 33, z, `${quartzStairs}[facing=east,half=top]`);
    set(10, 33, z, `${quartzStairs}[facing=west,half=top]`);
    set(9, 34, z, quartz);
  }
  set(9, 33, 11, `${quartzStairs}[facing=south,half=bottom]`);
  set(9, 34, 11, `${quartzStairs}[facing=south,half=top]`);

  // Top Target Acquisition Sensor & Master Lightning Mast (y=34..35)
  set(9, 34, 8, seaLantern);
  set(9, 35, 8, "minecraft:lightning_rod[facing=up]");
  set(9, 34, 6, "minecraft:lightning_rod[facing=north]");

  // Commit blocks to output
  for (const [key, block] of grid.entries()) {
    const [x, y, z] = key.split(",").map(Number);
    api.set(x, y, z, block);
  }

  return {
    name: "Colossus Defense Turret",
    seatY: 0,
    anchors: {
      front: [9, 1, 0],
      door: [9, 1, 17],
      battery_left: [7, 24, 0],
      battery_right: [11, 24, 0],
      radar: [9, 35, 8],
      command: [9, 2, 9]
    },
    interiors: [
      {
        min: [5, 1, 5],
        max: [13, 5, 13],
        kind: "vault"
      }
    ]
  };
}

