export const envelope = [16, 14, 18];

export default function build(api) {
  var SX = 16;
  var SY = 14;
  var SZ = 18;

  var MAT_AIR = 0;
  var MAT_DARK_PRISM = 1;
  var MAT_PRISM_BRICK = 2;
  var MAT_PRISM = 3;
  var MAT_BELLY = 4;
  var MAT_LANTERN = 5;
  var MAT_BONE = 6;
  var MAT_BLACKSTONE = 7;

  var grid = new Uint8Array(SX * SY * SZ);
  var strideY = SZ;
  var strideX = SY * SZ;

  function getV(x, y, z) {
    if (x < 0 || x >= SX || y < 0 || y >= SY || z < 0 || z >= SZ) return 0;
    return grid[x * strideX + y * strideY + z];
  }

  function setV(x, y, z, val) {
    var ix = Math.floor(x);
    var iy = Math.floor(y);
    var iz = Math.floor(z);
    if (ix >= 0 && ix < SX && iy >= 0 && iy < SY && iz >= 0 && iz < SZ) {
      grid[ix * strideX + iy * strideY + iz] = val;
    }
  }

  function drawCapsule(p1, p2, r1, r2, mat) {
    var dx = p2[0] - p1[0];
    var dy = p2[1] - p1[1];
    var dz = p2[2] - p1[2];
    var lenSq = dx * dx + dy * dy + dz * dz;
    var maxR = Math.max(r1, r2);
    var minX = Math.max(0, Math.floor(Math.min(p1[0], p2[0]) - maxR - 1));
    var maxX = Math.min(SX - 1, Math.ceil(Math.max(p1[0], p2[0]) + maxR + 1));
    var minY = Math.max(0, Math.floor(Math.min(p1[1], p2[1]) - maxR - 1));
    var maxY = Math.min(SY - 1, Math.ceil(Math.max(p1[1], p2[1]) + maxR + 1));
    var minZ = Math.max(0, Math.floor(Math.min(p1[2], p2[2]) - maxR - 1));
    var maxZ = Math.min(SZ - 1, Math.ceil(Math.max(p1[2], p2[2]) + maxR + 1));

    for (var x = minX; x <= maxX; x++) {
      for (var y = minY; y <= maxY; y++) {
        for (var z = minZ; z <= maxZ; z++) {
          var t = 0;
          if (lenSq > 0.0001) {
            t = ((x - p1[0]) * dx + (y - p1[1]) * dy + (z - p1[2]) * dz) / lenSq;
            if (t < 0) t = 0;
            else if (t > 1) t = 1;
          }
          var cx = p1[0] + t * dx;
          var cy = p1[1] + t * dy;
          var cz = p1[2] + t * dz;
          var r = r1 + t * (r2 - r1);
          var distSq = (x - cx) * (x - cx) + (y - cy) * (y - cy) + (z - cz) * (z - cz);
          if (distSq <= r * r) {
            setV(x, y, z, mat);
          }
        }
      }
    }
  }

  function rng() {
    return api.random();
  }

  var instIdx = api.instance.index;
  var poseType = instIdx % 3;
  var finStyle = (instIdx + Math.floor(rng() * 2)) % 3;
  var bellyType = (instIdx + Math.floor(rng() * 3)) % 3;

  var tailSide = (rng() > 0.5 ? 1 : -1) * (1.6 + rng() * 1.8);
  var headTurn = (rng() - 0.5) * 1.6;

  var chestY, headY, headZ, pelvisY, pelvisZ;
  if (poseType === 0) {
    pelvisY = 3.2 + rng() * 0.6;
    pelvisZ = 10.5;
    chestY = 6.0 + rng() * 1.4;
    headY = chestY + 1.8 + rng() * 1.2;
    headZ = 2.2 + rng() * 0.6;
  } else if (poseType === 1) {
    pelvisY = 2.8 + rng() * 0.5;
    pelvisZ = 10.8;
    chestY = 3.6 + rng() * 0.8;
    headY = 4.2 + rng() * 0.8;
    headZ = 1.8 + rng() * 0.5;
  } else {
    pelvisY = 3.2 + rng() * 0.6;
    pelvisZ = 10.2;
    chestY = 4.8 + rng() * 1.0;
    headY = chestY + 0.8 + rng() * 1.0;
    headZ = 1.6 + rng() * 0.4;
  }

  var pelvisX = 7.5 - headTurn * 0.3;
  var chestX = 7.5 + headTurn * 0.3;
  var headX = 7.5 + headTurn;

  var pPelvis = [pelvisX, pelvisY, pelvisZ];
  var pMidTorso = [7.5, (pelvisY + chestY) * 0.5, (pelvisZ + 5.5) * 0.5];
  var pChest = [chestX, chestY, 5.5];
  var pNeck1 = [chestX + (headX - chestX) * 0.4, chestY + (headY - chestY) * 0.4, 3.8];
  var pNeck2 = [chestX + (headX - chestX) * 0.8, chestY + (headY - chestY) * 0.8, headZ + 1.2];
  var pHead = [headX, headY, headZ + 0.6];

  // Draw main body core
  drawCapsule(pPelvis, pMidTorso, 2.7, 3.2, MAT_DARK_PRISM);
  drawCapsule(pMidTorso, pChest, 3.2, 3.4, MAT_DARK_PRISM);
  drawCapsule(pChest, pNeck1, 3.4, 2.5, MAT_DARK_PRISM);
  drawCapsule(pNeck1, pNeck2, 2.5, 2.1, MAT_DARK_PRISM);
  drawCapsule(pNeck2, pHead, 2.1, 1.8, MAT_DARK_PRISM);

  // Snout and Jaws
  var pSnout = [headX + (rng() - 0.5) * 0.4, headY - 0.2, headZ - 1.1];
  drawCapsule(pHead, pSnout, 1.7, 1.1, MAT_DARK_PRISM);

  var jawOpen = rng() > 0.3;
  var jawDrop = jawOpen ? (1.2 + rng() * 0.6) : 0.6;
  var pJawRoot = [headX, headY - 0.9, headZ + 0.5];
  var pJawTip = [headX, headY - jawDrop, headZ - 0.9];
  drawCapsule(pJawRoot, pJawTip, 1.2, 0.8, MAT_DARK_PRISM);

  // Teeth and Fangs
  var toothY = Math.round(headY - 0.7);
  var toothZ = Math.round(headZ - 0.6);
  setV(headX - 0.8, toothY, toothZ, MAT_BONE);
  setV(headX + 0.8, toothY, toothZ, MAT_BONE);
  setV(headX, toothY, Math.round(headZ - 0.9), MAT_BONE);
  if (jawOpen) {
    setV(headX - 0.6, Math.round(headY - jawDrop + 0.5), toothZ, MAT_BONE);
    setV(headX + 0.6, Math.round(headY - jawDrop + 0.5), toothZ, MAT_BONE);
  }

  // Glowing eyes and brow ridges
  var eyeY = Math.round(headY + 0.5);
  var eyeZ = Math.round(headZ + 0.4);
  setV(headX - 1.4, eyeY, eyeZ, MAT_LANTERN);
  setV(headX + 1.4, eyeY, eyeZ, MAT_LANTERN);
  setV(headX - 1.4, eyeY + 1, eyeZ, MAT_BLACKSTONE);
  setV(headX + 1.4, eyeY + 1, eyeZ, MAT_BLACKSTONE);

  // Head horns
  var hornEndL = [headX - 2.0, headY + 2.0 + rng() * 0.8, headZ + 2.6];
  var hornEndR = [headX + 2.0, headY + 2.0 + rng() * 0.8, headZ + 2.6];
  drawCapsule([headX - 1.0, headY + 1.1, headZ + 0.8], hornEndL, 0.8, 0.3, MAT_BLACKSTONE);
  drawCapsule([headX + 1.0, headY + 1.1, headZ + 0.8], hornEndR, 0.8, 0.3, MAT_BLACKSTONE);

  // Tail segments
  var tailJoints = [
    pPelvis,
    [pelvisX + tailSide * 0.3, pelvisY * 0.85 + 0.4, 12.3],
    [pelvisX + tailSide * 0.7, pelvisY * 0.7 + 0.9, 14.1],
    [pelvisX + tailSide * 1.0, pelvisY * 0.6 + 1.6, 15.6],
    [pelvisX + tailSide * 1.2, pelvisY * 0.5 + 2.2 + rng() * 0.8, 16.8]
  ];
  var tailRadii = [2.6, 2.1, 1.7, 1.2, 0.7];

  for (var i = 0; i < tailJoints.length - 1; i++) {
    drawCapsule(tailJoints[i], tailJoints[i + 1], tailRadii[i], tailRadii[i + 1], MAT_DARK_PRISM);
  }

  // Caudal tail fin blade
  var tip = tailJoints[tailJoints.length - 1];
  for (var dy = -1.5; dy <= 1.5; dy += 0.8) {
    drawCapsule(tip, [tip[0], tip[1] + dy, tip[2] + 0.5], 0.6, 0.2, dy === 0 ? MAT_LANTERN : MAT_PRISM);
  }

  // Forelimbs
  var leftHand = [
    chestX - 3.8 - rng() * 0.6,
    poseType === 0 ? 1.8 : 0.8,
    2.6 + rng() * 0.6
  ];
  var leftElbow = [chestX - 4.2, chestY - 1.2, 4.4];
  drawCapsule([chestX - 2.8, chestY + 0.2, 5.0], leftElbow, 1.6, 1.3, MAT_DARK_PRISM);
  drawCapsule(leftElbow, leftHand, 1.3, 1.1, MAT_DARK_PRISM);

  drawCapsule(leftHand, [leftHand[0] + 0.6, leftHand[1] - 0.6, leftHand[2] - 1.4], 0.6, 0.2, MAT_BONE);
  drawCapsule(leftHand, [leftHand[0] - 0.2, leftHand[1] - 0.6, leftHand[2] - 1.7], 0.7, 0.2, MAT_BONE);
  drawCapsule(leftHand, [leftHand[0] - 1.0, leftHand[1] - 0.6, leftHand[2] - 1.3], 0.6, 0.2, MAT_BONE);

  var rightHand = [
    chestX + 3.8 + rng() * 0.6,
    poseType === 0 ? (2.2 + rng() * 1.0) : 0.8,
    2.6 + rng() * 0.6
  ];
  var rightElbow = [chestX + 4.2, chestY - 1.0, 4.4];
  drawCapsule([chestX + 2.8, chestY + 0.2, 5.0], rightElbow, 1.6, 1.3, MAT_DARK_PRISM);
  drawCapsule(rightElbow, rightHand, 1.3, 1.1, MAT_DARK_PRISM);

  drawCapsule(rightHand, [rightHand[0] - 0.6, rightHand[1] - 0.6, rightHand[2] - 1.4], 0.6, 0.2, MAT_BONE);
  drawCapsule(rightHand, [rightHand[0] + 0.2, rightHand[1] - 0.6, rightHand[2] - 1.7], 0.7, 0.2, MAT_BONE);
  drawCapsule(rightHand, [rightHand[0] + 1.0, rightHand[1] - 0.6, rightHand[2] - 1.3], 0.6, 0.2, MAT_BONE);

  // Hind limbs
  var leftFoot = [pelvisX - 3.8, 0.8, pelvisZ + 1.6];
  var leftKnee = [pelvisX - 4.0, pelvisY - 1.2, pelvisZ + 0.5];
  drawCapsule([pelvisX - 2.4, pelvisY + 0.2, pelvisZ - 0.4], leftKnee, 1.7, 1.3, MAT_DARK_PRISM);
  drawCapsule(leftKnee, leftFoot, 1.3, 1.0, MAT_DARK_PRISM);
  drawCapsule(leftFoot, [leftFoot[0], leftFoot[1] - 0.5, leftFoot[2] - 1.2], 0.5, 0.2, MAT_BONE);
  drawCapsule(leftFoot, [leftFoot[0] - 0.8, leftFoot[1] - 0.5, leftFoot[2] + 0.8], 0.5, 0.2, MAT_BONE);

  var rightFoot = [pelvisX + 3.8, 0.8, pelvisZ + 1.6];
  var rightKnee = [pelvisX + 4.0, pelvisY - 1.2, pelvisZ + 0.5];
  drawCapsule([pelvisX + 2.4, pelvisY + 0.2, pelvisZ - 0.4], rightKnee, 1.7, 1.3, MAT_DARK_PRISM);
  drawCapsule(rightKnee, rightFoot, 1.3, 1.0, MAT_DARK_PRISM);
  drawCapsule(rightFoot, [rightFoot[0], rightFoot[1] - 0.5, rightFoot[2] - 1.2], 0.5, 0.2, MAT_BONE);
  drawCapsule(rightFoot, [rightFoot[0] + 0.8, rightFoot[1] - 0.5, rightFoot[2] + 0.8], 0.5, 0.2, MAT_BONE);

  // Dorsal Spines / Fins
  var spineNodes = [
    [pHead[0], pHead[1], pHead[2], 1.8],
    [pNeck2[0], pNeck2[1], pNeck2[2], 2.1],
    [pNeck1[0], pNeck1[1], pNeck1[2], 2.5],
    [pChest[0], pChest[1], pChest[2], 3.4],
    [pMidTorso[0], pMidTorso[1], pMidTorso[2], 3.2],
    [pPelvis[0], pPelvis[1], pPelvis[2], 2.7],
    [tailJoints[1][0], tailJoints[1][1], tailJoints[1][2], 2.1],
    [tailJoints[2][0], tailJoints[2][1], tailJoints[2][2], 1.7],
    [tailJoints[3][0], tailJoints[3][1], tailJoints[3][2], 1.2]
  ];

  for (var si = 0; si < spineNodes.length; si++) {
    var node = spineNodes[si];
    var topX = node[0];
    var topY = node[1] + node[2] * 0.05 + node[3];
    var topZ = node[2];

    if (finStyle === 0) {
      var finH = 1.4 + Math.sin((si / spineNodes.length) * Math.PI) * 2.2;
      var finTip = [topX, topY + finH, topZ + 0.5];
      drawCapsule([topX, topY - 0.6, topZ], finTip, 0.6, 0.2, (si % 2 === 0) ? MAT_DARK_PRISM : MAT_PRISM);
      if (si % 3 === 1) {
        setV(topX, topY + 0.5, topZ, MAT_LANTERN);
      }
    } else if (finStyle === 1) {
      var spineH = 1.6 + ((si * 7) % 3) * 0.8;
      var spineTip = [topX, topY + spineH, topZ + 0.8];
      drawCapsule([topX, topY - 0.4, topZ], spineTip, 0.7, 0.2, MAT_BLACKSTONE);
      setV(topX, topY, topZ, MAT_LANTERN);
    } else {
      var spineTipL = [topX - 0.8, topY + 1.4, topZ + 0.4];
      var spineTipR = [topX + 0.8, topY + 1.4, topZ + 0.4];
      drawCapsule([topX - 0.6, topY - 0.3, topZ], spineTipL, 0.5, 0.2, MAT_DARK_PRISM);
      drawCapsule([topX + 0.6, topY - 0.3, topZ], spineTipR, 0.5, 0.2, MAT_DARK_PRISM);
      setV(topX, topY - 0.2, topZ, MAT_LANTERN);
    }
  }

  // Bioluminescent flank nodes
  for (var bz = 4; bz <= 12; bz += 2) {
    var byL = Math.round(chestY - 0.5 + (bz % 3 === 0 ? 0.8 : -0.2));
    var bxL = Math.round(chestX - 2.8);
    if (getV(bxL, byL, bz) !== MAT_AIR && getV(bxL, byL, bz) !== MAT_BONE) {
      setV(bxL, byL, bz, MAT_LANTERN);
    }
    var bxR = Math.round(chestX + 2.8);
    if (getV(bxR, byL, bz) !== MAT_AIR && getV(bxR, byL, bz) !== MAT_BONE) {
      setV(bxR, byL, bz, MAT_LANTERN);
    }
  }

  // Shading & Scale Texture Pass
  for (var sx = 0; sx < SX; sx++) {
    for (var sz = 0; sz < SZ; sz++) {
      for (var sy = 0; sy < SY; sy++) {
        var v = getV(sx, sy, sz);
        if (v === MAT_DARK_PRISM) {
          if (sy <= 5 && (getV(sx, sy - 1, sz) === MAT_AIR || getV(sx, sy, sz - 1) === MAT_AIR)) {
            setV(sx, sy, sz, MAT_BELLY);
          } else {
            var isSurface = (
              getV(sx + 1, sy, sz) === MAT_AIR || getV(sx - 1, sy, sz) === MAT_AIR ||
              getV(sx, sy + 1, sz) === MAT_AIR || getV(sx, sy - 1, sz) === MAT_AIR ||
              getV(sx, sy, sz + 1) === MAT_AIR || getV(sx, sy, sz - 1) === MAT_AIR
            );
            if (isSurface) {
              var hash = Math.sin(sx * 12.9898 + sy * 78.233 + sz * 37.719) * 43758.5453;
              var rVal = hash - Math.floor(hash);
              if (rVal < 0.26) {
                setV(sx, sy, sz, MAT_PRISM_BRICK);
              } else if (rVal < 0.42) {
                setV(sx, sy, sz, MAT_PRISM);
              }
            }
          }
        }
      }
    }
  }

  // Follow terrain under all foot columns
  var footColumns = [
    [Math.round(leftHand[0]), Math.round(leftHand[2])],
    [Math.round(rightHand[0]), Math.round(rightHand[2])],
    [Math.round(leftFoot[0]), Math.round(leftFoot[2])],
    [Math.round(rightFoot[0]), Math.round(rightFoot[2])]
  ];

  for (var fi = 0; fi < footColumns.length; fi++) {
    var fx = footColumns[fi][0];
    var fz = footColumns[fi][1];
    if (fx >= 0 && fx < SX && fz >= 0 && fz < SZ) {
      var h = api.heightAt(fx, fz);
      var lowestY = SY;
      for (var y = 0; y < SY; y++) {
        if (getV(fx, y, fz) !== MAT_AIR) {
          lowestY = y;
          break;
        }
      }
      if (lowestY < SY) {
        var targetY = Math.max(0, Math.floor(h));
        for (var py = lowestY - 1; py >= targetY; py--) {
          setV(fx, py, fz, MAT_DARK_PRISM);
        }
      }
    }
  }

  function getBlockString(matId) {
    if (matId === MAT_DARK_PRISM) return "minecraft:dark_prismarine";
    if (matId === MAT_PRISM_BRICK) return "minecraft:prismarine_bricks";
    if (matId === MAT_PRISM) return "minecraft:prismarine";
    if (matId === MAT_BELLY) {
      if (bellyType === 0) return "minecraft:warped_wart_block";
      if (bellyType === 1) return "minecraft:oxidized_copper";
      return "minecraft:crying_obsidian";
    }
    if (matId === MAT_LANTERN) return "minecraft:sea_lantern";
    if (matId === MAT_BONE) return "minecraft:bone_block";
    if (matId === MAT_BLACKSTONE) return "minecraft:polished_blackstone";
    return "minecraft:dark_prismarine";
  }

  // Emit all voxels
  for (var emitX = 0; emitX < SX; emitX++) {
    for (var emitY = 0; emitY < SY; emitY++) {
      for (var emitZ = 0; emitZ < SZ; emitZ++) {
        var mat = getV(emitX, emitY, emitZ);
        if (mat !== MAT_AIR) {
          api.set(emitX, emitY, emitZ, getBlockString(mat));
        }
      }
    }
  }

  var anchorX = Math.max(0, Math.min(SX - 1, Math.round(headX)));
  var anchorY = Math.max(0, Math.min(SY - 1, Math.round(headY)));

  return {
    name: "sea_beast",
    seatY: 0,
    anchors: {
      front: [anchorX, anchorY, 0]
    }
  };
}
